    const result = await renderFetch(`/services/${SERVICE_ID}/env-vars/${id}`, {
      method: 'PUT',
      body: JSON.stringify(body),
    });
    console.log(`  Updated ${name}:`, result.ok ? 'OK' : `FAILED ${result.status}`, result.text.slice(0, 100));
    return result.ok;
