for path in files[:200]:
    try:
        with open(path, 'r', encoding='utf-8', errors='ignore') as f:
            text = f.read()
        # Search for Vercel API tokens
        for m in re.finditer(r'(vercel[A-Za-z0-9_]{20,}|vtoken_[A-Za-z0-9]+)', text, re.IGNORECASE):
            token = m.group(0)
            print(f'VERCEL TOKEN: {token[:30]}... in {os.path.basename(path)}')
    except:
        pass
" 2>/dev/null"}

